echo 'from dataclasses import dataclass
from typing import List, Optional, Sequence, Callable, Any, Union, Literal

@dataclass
class Depends:
    dependency: Optional[Callable[..., Any]] = None
    use_cache: bool = True
    scope: Union[Literal["function", "request"], None] = None

    def __hash__(self) -> int:
        return hash((self.dependency, self.use_cache, self.scope))

@dataclass
class Security(Depends):
    scopes: Optional[Sequence[str]] = None

    def __hash__(self) -> int:
        return hash((self.dependency, self.use_cache, self.scope, tuple(self.scopes) if self.scopes is not None else None))

d1 = Depends(dependency=lambda x: x)
d2 = Depends(dependency=lambda x: x)
print(f"Depends hashable: {hash(d1)}")

s1 = Security(dependency=lambda x: x, scopes=["admin"])
s2 = Security(dependency=lambda x: x, scopes=["admin"])
print(f"Security hashable: {hash(s1)}")
print(f"Security hashes match: {hash(s1) == hash(s2)}")
print(f"Security equals: {s1 == s2}")
' > /tmp/test_hash.py && python3 /tmp/test_hash.py

